import json

from hf_model import ask_model

from attendance_manager import (
    check_attendance,
    mark_attendance,
    remove_attendance,
    get_student_percentage,
    get_class_average
)


def execute_command(command):
    """Execute the command generated by the AI model."""

    action = command.get("action")

    if action == "check_attendance":

        return check_attendance(
            command.get("roll_no"),
            command.get("date")
        )

    elif action == "mark_attendance":

        return mark_attendance(
            command.get("roll_no"),
            command.get("date")
        )

    elif action == "remove_attendance":

        return remove_attendance(
            command.get("roll_no"),
            command.get("date")
        )

    elif action == "calculate_percentage":

        return get_student_percentage(
            command.get("roll_no")
        )

    elif action == "class_average":

        return get_class_average()

    else:

        return {
            "success": False,
            "error": "Unknown action"
        }


def main():

    print("=" * 50)
    print("       AI ATTENDANCE MANAGEMENT SYSTEM")
    print("=" * 50)

    print("\nAttendance period:")
    print("8 October 2026 - 14 October 2026")

    print("\nAvailable operations:")
    print("- Calculate attendance percentage")
    print("- Check attendance for a particular day")
    print("- Mark attendance")
    print("- Remove attendance")
    print("- Calculate class attendance average")

    print("\nType 'exit' to close the program.")

    while True:

        user_request = input("\nEnter your request: ")

        if user_request.lower() == "exit":
            print("\nProgram closed.")
            break

        try:

            # Send natural-language request to Hugging Face
            command = ask_model(user_request)

            print("\nAI Command:")
            print(json.dumps(command, indent=2))

            # Execute the command using Python
            result = execute_command(command)

            print("\nResult:")
            print(json.dumps(result, indent=2))

        except json.JSONDecodeError:

            print(
                "\nError: The AI model did not return valid JSON."
            )

        except Exception as error:

            print(
                f"\nError: {error}"
            )


if __name__ == "__main__":
    main()
